        public static List<TextEntry> Entries = new List<TextEntry>
        {
            new TextEntry{Title = "TUMELO YA KEREKE E NTJHA",Content = "TUMELO YA KEREKE E NTJHA\n\n1.Ke dumela o  modimo o mong feela,Mmmopi le Mmaballi wa ntho tsohle ya neng atle lefatsheng jwaleka Morena.Wa rona jesu Kreste,hotla lopolla le ho boloka batho.\n\n2.Ke Dumela  hore Morena  o ile A hlola Dihele ka ho lwantsha meleko yohle, mme ka hoo a lopolla Batho;mme hlolo yeo I ile yam o thusa ho tlotlisa both oba hae,A ba Molopolli le Mmoloki ka hosa feleng.\n\n3.Ke dumela hore boraro ba bomodimo,ke hore ntate le mora le moya o halalelang,Bo ho Morena Jesu Kreste,Boraro Bona ke Bomodimo Ka Sebele,Botho ba Bomodimo a Bolokang.\r\n4.Ke dumela hore Mangolo a Halalelang Ke Lentswe la Morena,le Sediba sa bohlale bohle ho mangeloi le batho.\n\n5.Ke dumela Haketla  bolokeha Ke tshwanetse ka matla a Morena ,ho Furalla makgopo ohle hobane ele dibe pel’a Hae ,Mme kebe le bophel obo Dumellanang le Melao ya hae.\r\n6.Ke dumela Hore Ha mmele Waka wa nama o eshwa ,ke tlanne ke phele lefatsheng la moya ka mmele waka wa moya.\n\n7.Ke dumela hore lebaka leo re bopilweng ka lona ke hore holte ho ebe lehodimo la mangeloi ,le hore bohle ba ditjhaba Tsohle ,ba dumelang Ho Modimo,ba ratang Beng ba bona,ba kena le hodimong haba eshwa;hape,lehodimo ke la bohle ba shwang esale bana;bohle ba kenang lehodimong ba eba le tshebetso e lokilengka hosa feleng.Athe bohle ba ratang bo kgopo ho feta Molem oba iketsetsa bodulo diheleng.\n\n8.Ke dumela hore Morena ose a tlile ha bobedi ,ka ho senola hlaloso ya moya ya lentswe la hae,leka dithuto tsa lehodimo tse fumanwang ho lona;le hore o theya kereke e ntja ,eo e leng moya o halalelang,Jerusalema e motjha o theohang ho modimo le hodimong.\n\n9.Ke dumela hore Paballo e akaretsang,yaka mehla,ya Morena wa rona,Oo mehauhelo yah ae e eleng Mesebetsing yohle yah ae.\n\n" },
            new TextEntry{Title = "MELAO  E LESHOME",Content = "MELAO  E LESHOME\n\nMoruti:       Yaba modimo o bolela Mantswe ana kaofela ,wa re:Ke nna jehova Modimo wa hao ,o u             Ntshitseng Egepeta,klung ya bohlanka.O seke waba le medimo e meng pela Sefahleho Sa ka.\r\nBatho:        Morena re utlwele bohlok o,mme o tiise dipelo tsa rona ,ho boloka molao ona.\r\nMoruti:      U seke wa iketsetsa setshwantsho se betlilweng ,le ha ele Setswhwantsho sele seng sa tse hodimo mahodimong,le ha ele sates tlase lefatsheng,le ha ele sa tse metsing ka tlase ho lefatshe,U seke wadi kgumamela ,u seke wadi sebeletsa hobane nna Jehova ,Modimo wa hao ,Ke Modimo ya boulelang,O otlang Bana ka Baka la bokgopo ba  Batswadi ba bona ho isa molokong wa boraro le wa bone w aba ntlhoyang;empa ke hauhelang ba  nthatang,Ba bolokang melao Yaka , ho isa melekong e seketa.\r\nBatho :Morena re utlwele Bohloko ,Mme  u tiise dipelo tsa rona ,ho boloka molao ona.\r\nMoruti      U seke watlaela ka lebitso la Jehova A ke ke  a latola molato way a tlaelang  ka lebitso la Hae.\r\nBatho:       Morena re Utlwele Bohloko ,mme u tiise dipelo tsa rona boloka molao Ona.\r\nMoruti:     Hopola letsatsi la phomolo ho le kgetha.Utla Sebetsa ka Matsatsi a Tsheletseng,Mme u etse mosebetsi kaofela .Empa letsatsi la bo Supa ke phomolo ya jehova,Modimo wa hao,u seke wa etsa mosebetsi le ole mong  ka letsatsi leo,le ha ele wena,le ha ele mora wa hao ,le ha ele mosadi wa hao,le ha ele mohlanka wa hao e motona,le ha e le ye motshehadi,le ha ele kgomo tsa hao,le ha e le moeti  wa hao yaka menyakong ya hao.Hobane ka matsatsi a tsheletseng ,Jehova one a etse Mahodimo le lefatshe,le lewatle,le ntho tsohle tse ho tsona,mme a phomola ka tsatsi le bosupa;ka baka lena Jehova o hlonolofaditse letsatsi la phomolo,mme ole beile le kgethileng.\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ho boloka molao ona.\r\nMoruti:        Hlonepha mmao le ntat;ao  le Mm’ao ,matsatsi a hao atle a eketsehe lefatsheng leo ole newang ke Jehova, Modimo wa hao\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ho boloka molao ona.\r\nMoruti:   U seke wa bolaya.\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ho boloka molao ona.\r\nMoruti :U seke wa feba.\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ho boloka molao ona.\r\nMoruti:U seke wa Utswa.\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ho boloka molao ona.\r\nMoruti:    U seke wa etselletsa wa heno ka leshano.\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ho boloka molao ona.\r\nMoruti:  u seke wa lakatsa ntlo yaw a heno.\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ho boloka molao ona.\r\nMoruti:U seke wa lakatsa mosadi wa hae le ha ele mohlanka wa hae emotona ,le ha ele e motshehadi,le ha ele kgomo yah ae,le ha ele esele yah ae,le ha lele ntho engwee e leng ya wa heno.\r\nBatho:    Morena re utlwele Bohloko ,mme u tiise dipelo tsa rona,ntate reya u rapela.\r\n" },
            new TextEntry{Title = "DIHLONOLOFATSO",Content = "DIHLONOLOFATSO\n\nHo lehlohonolo bafumanehi moyeng ,hobane muso wa mahodimo kewa bona.\r\nho lehlohonolo ba llang,hobane batla tshediswa \r\nHo lehlohonolo  ba bonolo ,hobane ba tlaja lefa la lefatshe\r\n Ho lehlohonolo ba laoelang ho loka,ba nyoretsweng hona ;hobane batla kgoriswa.\r\nHo lehlohonolo ba mohua ,hobane batla hauhelwa.\r\nHo lehlohonolo b aba pelo di hlwekileng ,hobane batla bona modimo.\r\nHo lehlohonolo ba etsang Kgahiso,hobane batla rewa bana ba Modimo.\r\nHo lehlohonolo ba hlorisetswang holoka ,hobane mmuso wa ma hodimo kewa Bona.\r\nLe tlaba lehlohonolo haba le hlapaola ka baka la ka,ba le hlorisa,ba le beya bobe bohle ka bohata.\r\nThabang le hlasimolohe kaho nyakalla ;hobane moputso wa lona otlaba moholo lehodimong;hobane ba hlorisitse jwalo baprofeta ba bileng teng pele ho lona.\r\nMatt. 5 :3-12).\r\n" },
            new TextEntry{Title = "KGUMAMELO YA LETSATSI LA MORENA",Content = "KGUMAMELO YA LETSATSI LA MORENA\n\nKa kerekeng ho tshwanetse ho eba Altare,mme hodima yon’a hobe lentswele kwahetseng ;mahlakoreng a lentswe hoka bewa di kandelara tse pedi kapa di pitsa tsa dipalesa,Altare  e bonwe ke batho bohle.Moruti le bareri le choir ba aparele tlung ya ho aparela.Ha base ba apere ka morao ho Thapelo,ba tlatswa bantse ba bina,ba entse mokoloko ho ya ka kerekeng.Ha base ba kene,pele ba fihla Altareng ,ba suthele moruti,ya tla feta hoya altareng.ha moruti ase ale Altareng a bule Lentswe,a retelehe ho batho ,mme a bale tse ding tsa ditemana tsena:\r\nJesu are tlong honna,lona bolhe ba kgathetseng ,ba imelwang ,ketla le imolla! Inkeleng Joko yaka mmele thute honna ,hobane ke mosa le pelo e nolo,mme letla fumaneha meya ya lona ya phomolo.Hobane  Joko yaka e tjhatsi,le phahlo yaka haena boima.\r\nLe yena e mobe, e kare ha kgeloha bobeng boo a neng a bo etsa,a etsa ka taelo le ka ho loka ,yena o pholosa moya wa hae.\r\nHaholang Dipelo tsa lona eseng diaparo tsa lona, mme le kgutlele ho jehova modimo wa lona ,hobane o le reko o pelo e telele o atisa ho hauhela ,o qenehela bao a itseng otlaba otla.\r\nKe tla tsoha keye ho Ntate ,mme ketlare ho yena ntate ke sitetswe le hodimo le wena, hakesa tshwanela ho bitswa mora wa hao ,o nketse ya jwaleka e mong wa bahlanka ba hao.\r\nMoruti le Phutheho batla kgumama ,ba rapele ka pelong tsa bona ,haba qetile hotla binwa.\r\nSEFELA\r\nBatho ba dutsi,Moruti otla bala \r\n" },
            new TextEntry{Title = "MEMO 1",Content = "MEMO\n\nBanabeso ba ratehang.\n\nMorena ole mema lentsweng la hae le halalelang hore remo rapele kadi pelo tsa rona le melomo ya rona.Ke mmopi wa rona.rona re mosebetsi wa matsoho a hae :Ke mmaballi wa rona ha ho motsotso  oo reka phelang kantle ho yena :Ke mmoloki h rona ke eena feela yaka rentshang tshenyehong .O lokile ho bohle,mme o hauhela le ba senang teboho  le ba babe ; athe ba moratang ka nnetse ba tsebang hore lerato la hao le nale matla ke bona feel aba fumanang tse ntle tse tswang ho yena .A re keng re nyoloseng mahlo a rona ho yena ,re a nyolosetse ho ntat’a rona ya bonang diphiri tsohle ,hobane Thapelo tsa rona tsa sephira  ha di  a lekana re tshwanetse ho kopana ha mmoho tlung ya Thapelo re utlwahatse merapelo ya ronaka melomo ya rona.Ke hona Morena atla utlwa merapelo ya rona,mme otlaba haufi le rona.Modimo wa rona,e leng mmoloki wa rona ore mema ka nako tsohle hore retle ho yena retlo fumana Bophelo ha reyeng ho yena ,re itiheleng pela sefahleho sa hae.Are utlweng ka boikokobetso dithuto tsa lentswe la hae tse halalelang le melao yah ae .Are mokopeng hore a tsholelle moya  wa hae o halalelang dipelong tsa rona,retle re fumane Bophelo .Are mo hodiseng bakeng sa dintle  tsa ho rona ,Tse tlang ka letsatsi le letsatsi \r\nA RE RAPELENG \r\nBatho haba kgumame ,moruti ha mmoho le phutheho bat la re:\r\nOho Morena Jesu Kreste ,Wena modimo wa rona le mmoloki wa rona ,Re I tihela pela sefahleho sa hao jwale ,ka boikokobetso bo boholo, le ka tsebo e phethahetseng ,ya boholo ba hao ,ya holoka ha hao ,le hore hare letho kantle ho wena .Rea tseba hore ,Morena,hore ka bo rona re keke ra etsa letho le lokileng ,hobane ke wena feela ya halalelang,ya refang molemo le nnete .Lokisa mehopolo ya rona le dipelo tsa rona ,retle re lokele ho atamela ,leho rorisa lebitso la hao ,refe moya wa boikokobetso Ntate ,retle re tsebe hore re dinthwwana feela tse sokolang ,tse sekamelang sebeng .Morena re hauheke,utlwa Thapelo tsa rona ka mosa ,le ka lerato la hao le leholo.Bopa ka hare ho rona pelo tse hlwekileng o bope ka hare ho rona Moya o tileng ,re thuse Morena ,retle rebe le hona ho atamela Altare ya hao ka di hlabelo tsa nnete tsa teboho le thoriso.AMEN\r\n" },
            new TextEntry{Title = "DITHAPELO 1",Content = "DITHAPEO\n\nOho Morena Jesu Kreste,Wena Morena modimo o matla hohle,Modimo o halalelang,Wena ya neng a theohe lefathseng ka baka la ho rata motho,ho tla batla le ho boloka ba lahlehileng rea u rapela,U ke u re thswarele ka baka la mohua wa hao.Wena ya mahlo a hlwekileng ,a tshabang le bobe,ya sitwang ho tadima hloriso,U tadimelang ba thetsi ,hobane   ha ho motho yaka fumanwang a lokile pela hao .Retla ho wena ka boikokobetso ,le ka Tshepo ya thato ya hao ya ho boloka ,refe matla re furalle makgopo a hao ,hobane ele dibe pel’a hao .Tlosa ho rona ditakatso tse mpe ,wena ya tseba ho fetola dipelo,mme u resitse ka lerato la hao .tebisa motheo wa mahlohonolo a lehodimo hodima rona ,mme u re hodisetse tumelong ya nnete kerekeng ya hao  lefatsheng lena,qetellong retle rebe mangeloi a mmuso wa hao ,AMEN.\r\n\r\nOho Morena Jesu Kreste ,Wena Lesedi la nnete ,le bonisetsang mang le mangy a tlang lefatsheng ,ako itlhahise lentsweng  la hao la nnete le balwang pel’a bath oba hao .Re nehele ho Utlwisisa Kganya ya lona ,mme le re senonele bohlale bale Hodimo ;Leke le retshedise mahlomoleng a rona ,le re matla fatse mefokolong rona,le retsamayise ditseleng tsa kgotso .tutubolla mahlo a rona ,re tle re bohisise mehlolo e patilweng molaong wa hao.Dikeletso tsa hao le tsona ke Menyaka ya rona le baeletsi ba rona.U re senolele tsela ya ditemoso tsa hao ,re tle re bohe mesebetsi ya hao e makatsang.Refe kutlwisiso,retle re boloke melao ya Hao re etse ka yona ka Pelo tsa roan tsohle.AMEN\r\n" },
            new TextEntry{Title = "THAPELO YA MORENA",Content = "THAPELO YA MORENA\n\nNtat’a rona ya mahodimong ,lebitso la lao leke le kgethehe,ho tle mmuso wa hao ,Jwaleka thato ya hao e etswa lehodimong ,le lefatsheng e etsuwe jwalo ,U refe kajeno, Bohobe ba rona ba Tsatsi le leng le le leng ;U re tshwarele melato ay rona :U seke ware isa molekong;U mpe u re lwele ho ye Mobe ,Hobane Mmuso ke wa hao ,le matla le Kganya ,Ka ho sa feleng .AMEN\r\nBohle ba ntse ba kgumame\r\nMoruti :   Morena Ahlamisa melomo ya rona.\r\nPhutheho: Mme melomo ya rona etla utlwahatsa dithoko tsa hao .\r\nMoruti:    Oho,Modimo,Phakisa hore Pholosa\r\nPhutheho: Oho,Morena<Phakisa o re thuse.\r\nBohle bae me\r\nMoruti: ho Jesu Kreste ebe Borena Le kganya  ka mehla le  ka mehla!\r\nPhutheho: Ke yena Alpha le Omega ,Qalo le Qetello ,Wa pele le wa morao ,ya leng teng ,Ya neng ale teng ,ya tlanne abe teng ,ya matla hohle.\r\nHo ka binwa Venite kapa Magnificat\r\n" },
            new TextEntry{Title = "VENITE,EXULTIMAS DOMINO",Content = "VENITE,EXULTIMAS DOMINO\n\nTlong,re phahamietseng dipina tsa rona ho Morena:\r\n             Le mehoo ya rona ya nyakallo ho lefika la poloko ya rona.\r\nRe itlhahiseng ho yena ka diteboho:\r\n             Re utlwahatse ditlatse tsa roan ka difela pel’a hae.\r\nHobane Morena ke Modimo o moholo\r\n            Ke Morena o moholo ya fetang Medimo yohle.\r\nMatebo a lefatshe a diatleng tsa hae:\r\n            Le oona maphahamo a dithaba.\r\nLewatle ke la hae,Ke mosebetsi wa Hae :\r\n           Le lona lefatshe le tiileng le bopilwe ke diatla tsa hae.\r\nTlong,Re kgumameng, re inameng:\r\n           Re we ka mangole pel’a Morena ,Mmopi wa rona.\r\nHobane yena ke Morena ,Modimo wa rona:\r\n           Re setjhaba seo a leng modisa sona ,mohlape o tsamaiswang ke letsoho la hae.\r\nKajeno hale Utlwa lentswe la hae le seke la thatafatsa Dipelo tsa lona:\r\n          Jwaleka ka mohla phephetso,mohl’a moleko,felleng\r\nMoo bo -ntat’a Lona ba nkileng teng:\r\n          Ba nteka ,le ha ba bone diketso tsaka.\r\nKa tenwa ke moloko oo ka dilemo tse mashome a mane,ka re:\r\n          Ke setjhaba seo pelo ya sona e kgelohileng,mme haba tsebe di tsela tsa ka.\r\nKe moo ke hlapantseng  bohaleng ba ka,ka re:\r\n         Ba k eke b aba ba Kena Phomolong ya ka.\r\nHo jesu Kreste ebe borena le kganya ka mehla le ka mehla:\r\n        Ke Alpha le Omega Qalo le qetello wa pele le wa morao ,ya leng teng ,ya neng a le teng ,ya matla ohle.\r\nPALO YA PELE \r\n(TESTAMENT YA KGALE)\r\nHoka binwa Te Deum kapa Magnificat\r\nTe Deum Laudamus\r\nRea u boka ,Modimo:\r\n            Rea bolela ,re re ,ke wena Morena.\r\nLefatshe lohle lea o khumamela:\r\n           Ntate ya phelang ka hosa feleng.\r\nMangeloi ohle a ntse a hoeletsa ho wena:\r\n         Mahodimo le dinatla tsohle tse ho ona.\r\nKerubime le Serufime:\r\n        Esale ntse di hweletsa dire.\r\nWa halalela, Wa halalela, Wa halalela:\r\n        Jehova Modimo wa makgotla.\r\nLehodimo le lefatshe di tletse:\r\n       Bohodimodimo jwa kganya ya Hao.\r\nLekgotla le tlotlehileng la Baapostola:\r\n       Le-ya u boka.\r\nPhutheho e kgabileng ya Baprofeta:\r\n       E-ya u boka.\r\nMakgotla a kgabane a bashwedi:\r\n      A u boka.\r\nKereke e halalelang e lefatsheng lohle:\r\n      E ntse e bolela Wena.\r\nKe wena Ntate:\r\n       U na le borena bo hlolang ka mehla.\r\nKe wena Mora:\r\n      Ke wena molopolli wa rona\r\nKe wena moya o halalelang:\r\n       Momatlafatsi.\r\nKe wena Modimo wa kganya:\r\n      Wena Kreste.\r\nKe wena  Modimo yasa Feleng:\r\n       Ke wena Ntate.\r\nMohlang  u nong o rerile ho lopolla batho:\r\n         Ha wa ka wa ila popelo ya morwetsana.\r\nEitse ha u hlotse bohale ba Lefu:\r\n        U buletse badumedi bohle mmuso wa lehodimo.\r\nU busa mahodimo ohle:\r\n        Ka kganya hao e kgolo\r\nReya kgolwa hoba o tla tla :\r\n      U be moahlodi wa rona.\r\nKa baka lena re ya u rapela ,re re ,thusa bahlanka ba hao:\r\n           Bao u ba lopollotseng ka madi a hao a bohlokwa.\r\nBa balwe le bahalaledi Ba hao:\r\n       Kganyeng esa felleng\r\nOho Morena pholosa setjhaba sa hao :\r\n        U hlonolofatse lefa la hao.\r\nU b abuse:\r\n          U ba phahamise ka hosa feleng.\r\nKa letsatsi le letsatsi:\r\n          Reya U hodisa.\r\nMme re rorisa lebitso la hao:\r\n         Ka hosa feleng.\r\nRe thuse Morena:\r\n         Re se wele Sebeng Tsatsing Lena.\r\nOho ,Morena ,re hauhele:\r\n          Re Hauhele Morena.\r\nOho,Morena Mohau wa hao o re fihlele:\r\n          Jwaleka re fela re u tshepile\r\nOho Morena re Itshepetse wena:\r\n          Ke seke ka swabiswa ka hosayeng kae.\r\n" },
            new TextEntry{Title = "MAGNIFICAT",Content = "Moya waka o hodisa Morena:\n\n        Moya waka o inyakalletse Modimong, mmoloki wa me.\r\nHobane o tadimile:\r\n        Bofutsana lekgabunyane la hae.\r\nMme jwale Meloko yohle:\r\n         E tlare ke lehlohonolo.\r\nHobane ya matla o nketseditse tse kgolo:\r\n        Lebitso la hae leya halalela.\r\nMme mohau wa hae oya hoba motshabang:\r\n         Melokong ya meloko.\r\nO sebeditse ka matla ka Letsoho la hae:\r\n       O qhalantse ba ikgomositseng mehopolong ya  dipelo tsa bona.\r\nO dihile babusi Diteroneng tsa bona:\r\n         Mme o phahamisitse ba banyenyane\r\nBa lapileng o ba kgurisitse tse molemo:\r\n       Mme ba ruileng o ba kgutlisitse ba sena letho.\r\nO babaletse Isiraele mohlanka hae,a hoopla mohau:\r\n         Kamoo a neng a baletse baholo ba rona ,Abrahama le leloko la hae ka ho sa yeng kae.\r\nPalo ya bodedi\r\n(testamente e ntjha)\r\nHoka balwa MELAO E LESHOME kapa MELAO E MEBEDI E MEHOLO,kapa DIHLOHONOLOFATSO(Matheu 5)Jwake, ka mora molao o mong le o mong ,phutheho e tla  bina mantswe ana :\r\nMorena re utlwile bohloko ,mme u tiise dipelo tsa rona,ho boloka molao wa hao!\r\nHa melao yohle ese e badilwe pgutheho e tla bina mantswe ana:\r\nMorena re utlwele bohloko,u ngole melao ena dipelong tsa rona,Ntate reya ho rapela.\r\nBOIPOLELO BA TUMELO\r\nKe dumela hore Morena le mmoloki wa rona Jesu Kreste ke yena fela modimo wa lehodimo le lefatshe ,le hore ho yena Ho boraro bo kgethehileng ba Ntate,mora,le moya o halalelang\r\nKe dumela hore haketla bolokeha ,ke tshwanetse ,ka matla a Morena,ho furalla Makgopo ohle hobane ele dibe pel’a hae ,mm eke be le Bophelo bo dumellanang le Melao yah ae e Leshome.\r\nKe dumela lentsweng la Modimo ,Kapa mangolong a halalelang,le dithutong tsa lehodimotsa Jerusalema e motjha,tse fumanweng lentsweng,mme tsa akaretswa Mangolong a tsa Modimo a Emmanuel Swedenborg.\r\nHa moruti le bath oba se ba entse boipolelo ba tumelo bo ka hodimo ,Moruti o tla re:\r\nMoruti: Morena abe le lona\r\nBatho :Mme a be le moya wa hao.\r\nMoruti: A re rapeleng.\r\n" },
            new TextEntry{Title = "DITHAPELO 2",Content = "DITHAPELO\n\nMorena Jeso ya Matla ,Wena ya tshepisitseng hotla labobedi,Wena ya tsosang kereke eo ho yona ho rutwang dithuto tsa nnetetsa tsebo ya hao,reya u rapela,Hodisa mosebetsi ona wa hao o moholo .A motse o halalelang,Jerusalema e motjha,o theohe lehodimong ho modimo ,mme bohle ba bone kganya ya ona,,ba rapele wena u inotshi,bat le ba apeswe  ka matla a Sione,e leng se aparo se Kganyang sa Jerusalem.Ba ke ba kopanye di nnete tsena le lerato la hao la ho ratana.A ba rapelamg lebitso la hao le halalelang ba hlokomele ho boloka melao ya hao ;kereke ya hao e tle e hole lefatsheng ka dithuto tsa moya le nnete e hlwekileng.AMEN\r\nOho Morena Jesu,Wena mong’a kereke ;hlonolofatsa ba hlanka ba hao ba mose ho mawatle ,ba ntseng ba sebetsa ka matla hore Evangedi ena entja ,ya hotla ha hao ha bobedi,e tsejwe ke ditjhaba tsohle.Ba ekeletse matla ,hore  ka bona, le rona,lefatshe lohle le tle le amohele dithuto tsemakatsang tsa Jerusalema e mocha,tse senotsweng ka mohlanka hao,Emmanuel Swedenborg.Tsosa baruti ba nang le borapedi ban nete,mme ba rute ditjhaba Evangedi ya nnete.Kotulo e kgolo,Empa basebetsi ha ba bakae.Oho Morena Kotulo ,romela basebetsi tshimong ya hao.Tlatsa dipelo tsa bona ka lerato la dinnete tsa hao,bula mehopolo ya bona ka Lesedi la bohlale ba nnete ,mme u bafe matla a ho bolela Evangedi ya hao ka Tjheseho.AMEN.\r\nMookamedi ya renang mebusong yohle ya lefatshe,Morena wa marena le Mmusi wa ba busi,hlohonolofatsa lefatshe la rona la Afrika .Eba le marena a rona le babusi ba ditjhaba.batshele moya hao ,ba tle ba be le hona hore busa ka toka leka lerato.eba le baahlodi ba rona,o bafe moya wa nnete wa toka..Eba le lefatshe lohle ,le ditjhaba tsohle ,di tle di ahlolelwe ke wena,le mefuta e mengata e lauwe ke wena,batle ba teye di phehla tsa bona tsa ntwa mehoma,le marumo a bona ba a teye disekele.Setjhaba se seng se seke sa hlola se futuhela setjhaba se seng ka lerumo,le ho lwana ebe habasa I thuta hona .AMEN.\r\nNtate ya mohau osa feleng,sheba bakudi ba rona ka leihlole mosa,mme oba tsose diphateng tsa bona.Jwaleka ha o kile wa bolella Johanne mehleng yak gale,etsa difofu tsa rona di bone,dihlotsa di tsamaye,balepera ba ntlafale ,ba thibaneng ditsebe ba utlwe,bafu ba tsowe,bafutsana ba bolellwe Evangedi.Apesa dingaka tsa rona le baoki ba rona matla a phodiso a tswang ho wena,hore ka wena mosebetsi wa bona otle o atlehe Sireletsa bahlolohadi ba rona le dikgutsana,mme o tjhabisetse ba kgolehong le ba hole le lehae letsatsi la ho loka,ba tsebe hore wenuh Morena jehova,ha u thabele lefu ya a Shwang ,empa o rata  ha moetsadibe a ka sokoloha ,mme a phela.AMEN\r\nModimo a matla ohle,a re hauhetseng motsotsong ona,hore retle ka tumellano ho u hlahisetsa  hammoho  merapelo ya rona, Mme ore tshepisitse hore moo ba babedi kapa ba bararo ba  phuthehileng teng ka lebitso la hao U tla bafa seo base kopang ,Phetha jwalo Morena ,ditakatso le dithapelo tsa bahlanka ba hao kamoo o bonang hore ho ka ba lokela,lefatsheng leena ore nee tsebo ya nnete ya hao,mme lefatsheng le tlang o re nee  Bophelo bosa feleng.AMEN.\r\nMOHAU\r\nMohau wa Morena wa rona jesu Kreste obe le lona bohle.AMEN\r\nSEFELA\r\nDITSEBISO\r\nTHUTO\r\nSEFELA\r\nHLONOLOFATSO\r\nJehova ale hlonolofatse mme a le boloke ;\r\nJehova a le Kgantshetse sefahleho sa hae,mme ale hauhele;\r\nJehova a retelletse sefahleho sa hae ho lona,mme a lefe kgotso.AMEN\r\n" },
            new TextEntry{Title = "LETSATSI LA TWALO YA MORENA JESO",Content = "LETSATSI LA TWALO YA MORENA JESO\n\nKa mora sefela ,moruti otla bala temana tsena tse latelang:\r\nKe le bolella thabo e kgolo ,e monate,ee e tlaba ya setjhaba kaofela;ke hore,kajeno ,le tswalletswe mmoloki,Motseng wa Davida, ke Kreste ,Morena.\r\nHobane re tswaletswe ngwana,re neilwe mora;Borena bo beilwe lehetleng la hae,mme otla bitswa Moeletsi,ya Makatsang,Modimo ya Matla,Ra-bo-sa-feleng,Morena wa kotso,hore o hodise mmuso,le ho tlisa kgotso esa feleng.\r\nKganya ebe ho Modimo,mahodimong a hodimo,Kgotso ebe lefatsheng ho batho bao o kgahlwang ke bona.\r\nJwale phutheho etla dula ,mme moruti otla bala MEMO ena e latelang\r\n" },
            new TextEntry{Title = "MEMO 2",Content = "MEMO\n\nBana beso ba ratehang\r\nRe kopane Hammoho Nakong ena,hotla rorisa Morena ka baka la kgauhelo yah ae e kgolo,e ileng yamo tlisa lefatsheng lena,ho tlaba motho jwaleka rona,mme ka botho boo abe le hona hore lopolla ele hona hore boloka,re thabela tswalo yah ae Bethlehema,ka tsebo e phethahetseng ya hore kantle ho yena ho no ho se ya ka re bolokang,ona atle ka lerato le leholo,leka kutlwelo bohloko,mme le tsoho la hae le ile la mo thusa ho hlola dihele tse neng di hatelletse bathobohle,di ba entse Makgoba.Ka ho re tlotlisa botho bah ae,O bile mofenyi wa nako tsohle,mme O nale borena bohle mahodimong le lefatsheng.Tsebang ke hona,hore ka ntle ho yena ha ho letho le  reka le etsang,mme hare moleboheng ka dipelo tsa rona tsohle.\r\nA  re rapeleng\r\nOho Morena\tJesu Kreste ,wena U neng  U tle neng U tle lefatsheng ho tla batla le ho boloka ba lahlehileng,U re  bontshitse kamoo re tshwanetseng ho tsamaya ka teng bophelong bona,mme ka wena bafokodi ba bona matla.U seke ware tlohellela dira tsa rona.A Lesedi la  hao le le lekele meya ya lefifif.Kgaola mahlaahlela are tlamileng,re tswe kgolehong re fumane tokoloho ya Hao re be leseding.AMEN\r\nOho Morena,wena ya hlonolofaditseng Malapa ohle a mona lefatsheng,eba le bana ba hao bohle Nakong ena ya thabo,Eba le rona ha re thabela dijo tse re di fumaneng ho wena,ha Malapa ohle a kopane hammoho ka thabo le Kresemese.Bana ba nyakalle ka thabo,baholo ba be le matla le Tshepo,batsofadi ba be le  thabo le kgotso matsatsing a bona a ho fela.Eba le ba leng siyo hae, ba be le thabo ya letsatsi lena.Re thuse bohle ,re amohele lerato la hao le leholo,le rona re ratane ho fitisa,re tshepane dinakong tseo re leng ho tsona.Ha re hoopla tse monate tse fitileng ,re fe Tshepo ya tse ntle tse tlang,re seke ra lebala hore U teng meketeng ya rona.AMEN \r\n" }
        };
    }
}
